package com.example.yuejie;
import android.app.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import static com.example.yuejie.PaperUi.*;
final class ChapterSheet {
 interface Choose{void at(int index);}
 static void show(Activity a,String title,JSONArray chapters,int selected,Choose choose,boolean night,Runnable refresh){
 int paper=night?0xff28332a:PAPER,ink=night?0xffd9dfd3:INK,green=night?0xffabc3a4:GREEN;Dialog dialog=new Dialog(a);LinearLayout root=col(a);root.setPadding(dp(a,24),dp(a,16),dp(a,24),dp(a,20));root.setBackground(bg(a,paper,20));LinearLayout header=row(a);TextView heading=heading(a,title,18);heading.setTextColor(ink);heading.setMaxLines(1);heading.setEllipsize(android.text.TextUtils.TruncateAt.END);header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));if(refresh!=null){TextView update=button(a,"刷新",()->{dialog.dismiss();refresh.run();});update.setBackground(bg(a,night?0xff303a2f:SOFT,10));update.setTextColor(green);header.addView(update);}header.addView(icon(a,"关闭",ink,44,()->dialog.dismiss()));root.addView(header);ListView list=new ListView(a);list.setDividerHeight(1);list.setBackgroundColor(paper);BaseAdapter adapter=new BaseAdapter(){public int getCount(){return chapters.length();}public Object getItem(int p){return chapters.optJSONObject(p);}public long getItemId(int p){return p;}public View getView(int position,View view,android.view.ViewGroup parent){JSONObject c=chapters.optJSONObject(position);TextView t=text(a,(position+1)+"    "+c.optString("title")+(c.optBoolean("locked")?"  ·  受限":""),13,position==selected?green:ink);t.setPadding(dp(a,2),dp(a,18),dp(a,2),dp(a,18));t.setMinHeight(dp(a,52));if(position==selected)t.setBackground(bg(a,night?0xff303a2f:SOFT,6));return t;}};list.setAdapter(adapter);list.setOnItemClickListener((p,v,index,id)->{dialog.dismiss();choose.at(index);});root.addView(list,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(root);Window w=dialog.getWindow();w.setBackgroundDrawableResource(android.R.color.transparent);w.setGravity(Gravity.BOTTOM);w.setDimAmount(.2f);dialog.show();w.setLayout(-1,(int)(a.getResources().getDisplayMetrics().heightPixels*.7));if(selected>=0)list.setSelection(selected);
 }
}
